/// True for a double-quote character (code 34).
fn is_quote(c: Str) -> Bool {
  return c.codes().get_or(0, 0) == 34
}

/// Splits one CSV line into fields; quoted fields may hold commas and "" escapes.
pub fn parse_csv_line(line: Str) -> Result[List[Str], Str] {
  let chars = line.chars()
  let n = chars.len()
  var fields: List[Str] = []
  var cur = ""
  var in_q = false
  var i = 0
  while i < n {
    let c = chars.get_or(i, "")
    if in_q {
      if is_quote(c) {
        if i + 1 < n and is_quote(chars.get_or(i + 1, "")) {
          cur = cur + c
          i = i + 2
        } else {
          in_q = false
          i = i + 1
        }
      } else {
        cur = cur + c
        i = i + 1
      }
    } else if is_quote(c) {
      in_q = true
      i = i + 1
    } else if c == "," {
      fields = fields.push(cur)
      cur = ""
      i = i + 1
    } else {
      cur = cur + c
      i = i + 1
    }
  }
  if in_q {
    return Err("unterminated quote")
  }
  fields = fields.push(cur)
  return Ok(fields)
}
